import React, { useState } from 'react';
import api from '../api';
import { useLiquidGlass } from '../hooks/useLiquidGlass';

const AuthModal = ({ onAuthSuccess, showToast }) => {
    const [isRegister, setIsRegister] = useState(false);
    const [fullName, setFullName] = useState('');
    const [email, setEmail] = useState('client@ticketflow.ro');
    const [password, setPassword] = useState('client123');
    const [role, setRole] = useState('CLIENT');
    const [loading, setLoading] = useState(false);

    const { rootRef } = useLiquidGlass([isRegister], {
        cornerRadius: 32,
        refraction: 0.82,
        blurAmount: 0.24,
    });

    const quickFill = (demoEmail, demoPwd) => {
        setIsRegister(false);
        setEmail(demoEmail);
        setPassword(demoPwd);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        try {
            const endpoint = isRegister ? '/auth/register' : '/auth/login';
            const payload = isRegister ? { fullName, email, password, role } : { email, password };
            const res = await api.post(endpoint, payload);
            localStorage.setItem('tf_token', res.data.token);
            localStorage.setItem('tf_user', JSON.stringify(res.data.user));
            onAuthSuccess(res.data.user);
            showToast(`Signed in as ${res.data.user.fullName}`, 'success');
        } catch (err) {
            showToast(err.response?.data?.message || 'Authentication failed', 'error');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div ref={rootRef} className="min-h-screen flex items-center justify-center p-4 relative">
            {/* Sampled Background Sibling */}
            <div className="lg-backdrop-mesh" />

            {/* Direct-Child WebGL Glass Panel */}
            <div className="lg-surface z-10 max-w-md w-full rounded-[32px] p-8 sm:p-10 space-y-6">
                <div className="text-center space-y-1.5">
                    <div className="w-12 h-12 mx-auto rounded-2xl bg-white/15 border border-white/25 flex items-center justify-center text-xl">
                        🎟️
                    </div>
                    <h1 className="text-2xl font-bold tracking-tight text-white">TicketFlow</h1>
                    <p className="text-xs text-white/60">Spatial Event Access &amp; Smart Ticketing</p>
                </div>

                {/* Segmented Role Switcher */}
                <div className="clean-well rounded-2xl p-1.5 grid grid-cols-3 gap-1">
                    <button
                        type="button"
                        onClick={() => quickFill('client@ticketflow.ro', 'client123')}
                        className={`py-2 rounded-xl text-xs font-semibold transition ${
                            email === 'client@ticketflow.ro' && !isRegister ? 'bg-white text-slate-950' : 'text-white/65 hover:text-white'
                        }`}
                    >
                        Client
                    </button>
                    <button
                        type="button"
                        onClick={() => quickFill('organizer@ticketflow.ro', 'org123')}
                        className={`py-2 rounded-xl text-xs font-semibold transition ${
                            email === 'organizer@ticketflow.ro' && !isRegister ? 'bg-white text-slate-950' : 'text-white/65 hover:text-white'
                        }`}
                    >
                        Organizer
                    </button>
                    <button
                        type="button"
                        onClick={() => quickFill('admin@ticketflow.ro', 'admin123')}
                        className={`py-2 rounded-xl text-xs font-semibold transition ${
                            email === 'admin@ticketflow.ro' && !isRegister ? 'bg-white text-slate-950' : 'text-white/65 hover:text-white'
                        }`}
                    >
                        Admin
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="space-y-4">
                    {isRegister && (
                        <>
                            <input
                                required
                                type="text"
                                value={fullName}
                                onChange={(e) => setFullName(e.target.value)}
                                placeholder="Full Name"
                                className="w-full px-4 py-3 rounded-2xl clean-well text-sm text-white placeholder-white/35 focus:outline-none focus:border-white/40"
                            />
                            <select
                                value={role}
                                onChange={(e) => setRole(e.target.value)}
                                className="w-full px-4 py-3 rounded-2xl clean-well text-sm text-white focus:outline-none focus:border-white/40"
                            >
                                <option value="CLIENT" className="bg-slate-950">Client</option>
                                <option value="ORGANIZER" className="bg-slate-950">Organizer</option>
                            </select>
                        </>
                    )}

                    <input
                        required
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        placeholder="Email"
                        className="w-full px-4 py-3 rounded-2xl clean-well text-sm text-white placeholder-white/35 focus:outline-none focus:border-white/40"
                    />

                    <input
                        required
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        placeholder="Password"
                        className="w-full px-4 py-3 rounded-2xl clean-well text-sm text-white placeholder-white/35 focus:outline-none focus:border-white/40"
                    />

                    <button disabled={loading} type="submit" className="w-full py-3.5 rounded-full apple-pill font-bold text-sm">
                        {loading ? 'Signing in...' : isRegister ? 'Create Account' : 'Continue'}
                    </button>
                </form>

                <div className="text-center pt-2">
                    <button
                        type="button"
                        onClick={() => setIsRegister(!isRegister)}
                        className="text-xs text-white/65 hover:text-white transition"
                    >
                        {isRegister ? 'Already have an account? Sign In' : 'Create a new account'}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default AuthModal;
